def find_rectangles(grid):
    """Find all hollow rectangular frames"""
    rects = []
    h, w = len(grid), len(grid[0])

    for r1 in range(h):
        for c1 in range(w):
            color = grid[r1][c1]
            if color == 0 or color > 9:
                continue

            # Look for horizontal continuation
            c2 = None
            for c in range(c1 + 1, min(c1 + 50, w)):
                if grid[r1][c] == color:
                    c2 = c
                else:
                    break

            if c2 is None or c2 <= c1 or (c2 - c1) < 3:
                continue

            # Look for vertical down from left edge
            r2 = None
            for r in range(r1 + 1, h):
                if grid[r][c1] == color:
                    r2 = r
                    break

            if r2 is None or r2 <= r1:
                continue

            # Must have bottom-right corner
            if grid[r2][c2] != color:
                continue

            # Verify frame
            valid = True
            # Top
            for c in range(c1 + 1, c2):
                if grid[r1][c] != color:
                    valid = False; break
            if not valid: continue
            # Bottom  
            for c in range(c1 + 1, c2):
                if grid[r2][c] != color:
                    valid = False; break
            if not valid: continue
            # Left
            for r in range(r1 + 1, r2):
                if grid[r][c1] != color:
                    valid = False; break
            if not valid: continue
            # Right
            for r in range(r1 + 1, r2):
                if grid[r][c2] != color:
                    valid = False; break
            if not valid: continue

            rects.append({'top': r1, 'bottom': r2, 'left': c1, 'right': c2, 'color': color})

    return rects

