def find_rectangles(grid):
    rects = []
    for r1 in range(height):
        for c1 in range(width):
            color = grid[r1][c1]
            if color <= 9 and color > 0:
                # Look right for horizontal line
                c2 = None
                for cc in range(c1 + 1, min(c1 + 50, width)):
                    if grid[r1][cc] == color:
                        c2 = cc
                    else:
                        break

                if c2 is None or c2 < c1: continue

                # Look down from left corner
                r2 = None
                for rr in range(r1 + 1, height):
                    if grid[rr][c1] == color:
                        r2 = rr
                        break

                if r2 is None or r2 <= r1: continue

                # Check if top-left corner could be start of rect
                # Must have right continuation AND bottom continuation
                if c2 > c1 and r2 > r1:
                    # Verify complete rectangle
                    valid = True

                    # Top edge
                    for cc in range(c1 + 1, c2):
                        if grid[r1][cc] != color:
                            valid = False; break
                    if not valid: continue

                    # Bottom edge
                    for cc in range(c1 + 1, c2):
                        if grid[r2][cc] != color:
                            valid = False; break
                    if not valid: continue

                    # Left edge
                    for rr in range(r1 + 1, r2):
                        if grid[rr][c1] != color:
                            valid = False; break
                    if not valid: continue

                    # Right edge
                    for rr in range(r1 + 1, r2):
                        if grid[rr][c2] != color:
                            valid = False; break
                    if not valid: continue

                    # Check corners are same color
                    if grid[r1][c2] != color or grid[r2][c1] != color:
                        valid = False; continue

                    rects.append({
                        'top': r1, 'bottom': r2, 
                        'left': c1, 'right': c2,
                        'color': color
                    })

    return rects

