def extract_grid(text_content):
    """Extract grid from text after 'XXX (HxW):' header"""
    lines = text_content.split('\n')
    in_section = False
    grid_rows = []

    for i, line in enumerate(lines):
        if '(18x23)' in line or '(20x20)' in line or '(22x26)' in line:
            # Check for dimension match
            dim = None
            if '(18x23)' in line: dim = 23
            elif '(20x20)' in line: dim = 20
            elif '(22x26)' in line: dim = 26

            # Look ahead for the actual grid data (not JSON)
            j = i + 1
            while j < len(lines):
                next_line = lines[j].strip()
                if not next_line:
                    j += 1
                    continue
                # Skip if this is JSON/log output
                if any(x in next_line.lower() for x in ['json', 'dumps', 're.finditer', '===']):
                    j += 1
                    continue
                # If it's a valid grid row (numbers)
                tokens = next_line.split()
                if len(tokens) > 0 and all(t.isdigit() for t in tokens[:min(dim, len(tokens))]):
                    grid_rows.append([int(x) for x in tokens])
                    if len(grid_rows) == dim:
                        break
                else:
                    break

        if grid_rows and len(grid_rows) == dim:
            return grid_rows

    return None

